484→/// This ensures the `SdkMeterProvider` is created with the correct resource,
485→/// so metrics recorded after this call will have the proper resource attributes.
486→#[must_use]
487→pub(crate) fn create_telemetry_with_resource(common: &CommonArgs, resource: Resource) -> Telemetry {
488→    if let Some(endpoint) = &common.otlp_endpoint {
489→        return Telemetry::with_otlp_resource(
490→            OtlpExporterConfig {
491→                endpoint: endpoint.clone().into(),
492→                headers: common.otlp_header.clone(),
493→                timeout: Duration::from_secs(10),
494→            },
495→            resource,
496→        );
497→    }
498→
499→    Telemetry::new_with_resource(&resource, "SPICEAI_BENCHMARK_METRICS_KEY")
