598→pub(crate) async fn get_app_and_start_request(
599→    args: &CommonArgs,
600→) -> anyhow::Result<(App, StartRequest)> {
601→    // When metrics are disabled, no Telemetry is created, so METER_PROVIDER_ONCE
602→    // remains unset and all metric operations are no-ops.
603→
604→    let mut spicepod = Spicepod::load_exact(args.spicepod_path.clone()).await?;
605→    let mut app_builder = AppBuilder::new(spicepod.name.clone()).with_spicepod(spicepod.clone());
606→
607→    if let Some(dependencies_root) = &args.spicepod_dependencies {
608→        for dependency in &spicepod.dependencies {
609→            let dependent_spicepod = Spicepod::load(&dependencies_root.join(dependency)).await?;
610→            app_builder = app_builder.with_spicepod_dependency(dependent_spicepod);
611→        }
612→    }
613→    // After we've loaded dependencies, remove.
614→    spicepod.dependencies = vec![];
615→    let app = app_builder.build();
616→
617→    let mut start_request = StartRequest::new(args.spiced_path_buf(), from_app(app.clone()))?;
618→
619→    if let Some(ref data_dir) = args.data_dir {
620→        start_request = start_request.with_data_dir(data_dir.clone());
621→    }
622→
623→    // If scrape_spiced_metrics is enabled, add --metrics flag to spiced
624→    if args.scrape_spiced_metrics {
625→        start_request = start_request
626→            .with_additional_args(vec!["--metrics".to_string(), "0.0.0.0:9090".to_string()]);
627→    }
628→
629→    Ok((app, start_request))
630→}
631→
632→pub(crate) async fn env_export(args: &CommonArgs) -> anyhow::Result<()> {
633→    let (_, mut start_request) = get_app_and_start_request(args).await?;
634→
635→    start_request.prepare()?;
636→    let tempdir_path = start_request.get_tempdir_path();
637→
638→    println!(
639→        "Exported spicepod environment to: {}",
640→        tempdir_path.to_string_lossy()
641→    );
642→
643→    // Wait for input before exiting
644→    println!("Press Enter to exit...");
645→    std::io::stdin().read_line(&mut String::new())?;
646→
647→    Ok(())
648→}
649→
650→#[macro_export]
651→macro_rules! wait_test_and_memory {
652→    ($test:expr, $memory_token:expr, $memory_readings:expr) => {
653→        match $test.wait().await {
654→            Ok(test) => test,
655→            Err(e) => {
656→                observe_memory($memory_token, $memory_readings).await?;
657→                return Err(e);
658→            }
659→        }
660→    };
661→}
662→
663→/// Process and display metrics from the spiced metrics scraper
664→///
665→/// # Arguments
666→/// * `scraper` - Optional metrics scraper to stop and process
667→/// * `emit_to_telemetry` - Whether to emit metrics to OpenTelemetry
668→/// * `attributes` - Optional attributes to attach to emitted metrics (e.g., test name)
669→///
670→/// # Returns
671→/// The collected `SpicedMetrics` if scraper was present, None otherwise
672→pub(crate) async fn process_spiced_metrics(
673→    scraper: Option<crate::spiced_metrics::MetricsScraper>,
674→    emit_to_telemetry: bool,
675→    attributes: &[test_framework::opentelemetry::KeyValue],
676→) -> Option<crate::spiced_metrics::SpicedMetrics> {
677→    let scraper = scraper?;
678→
679→    match scraper.stop().await {
680→        Ok(metrics) => {
681→            println!("\n{}", vec!["="; 30].join(""));
682→            println!("Spiced Runtime Metrics:");
683→            println!("{}", vec!["="; 30].join(""));
684→
685→            // Display and optionally emit key metrics
686→            // Note: Prometheus exporter appends _total to counter metrics
687→            if let Some(query_count) = metrics.get_counter_value("query_executions_total") {
688→                println!("Total Queries Executed: {query_count}");
689→
690→                if emit_to_telemetry {
691→                    crate::metrics::SPICED_QUERY_COUNT.record(query_count, attributes);
692→                }
693→            }
694→
695→            if let Some(cache_hits) = metrics.get_counter_value("results_cache_hits_total")
696→                && let Some(cache_requests) =
697→                    metrics.get_counter_value("results_cache_requests_total")
698→                && cache_requests > 0.0
699→            {
700→                let hit_rate = cache_hits / cache_requests;
701→                println!("Cache Hit Rate: {:.2}%", hit_rate * 100.0);
702→
703→                if emit_to_telemetry {
704→                    crate::metrics::SPICED_CACHE_HIT_RATE.record(hit_rate, attributes);
705→                }
706→            }
707→
708→            if let Some(active_conns) = metrics.get_gauge_max("query_active_count") {
709→                println!("Peak Active Connections: {active_conns}");
710→
711→                if emit_to_telemetry {
712→                    crate::metrics::SPICED_ACTIVE_CONNECTIONS.record(active_conns, attributes);
713→                }
714→            }
715→
716→            println!("{}", vec!["="; 30].join(""));
717→            Some(metrics)
718→        }
719→        Err(e) => {
720→            println!("Warning: Failed to collect spiced metrics: {e}");
721→            None
722→        }
723→    }
724→}
