476→        deploymentError,
477→      );
478→
479→      // Check for specific error types and return appropriate status codes
480→      const errorMessage =
481→        deploymentError?.message || 'Failed to create deployment';
482→
483→      // Concurrent deployment error - return 409 Conflict
484→      if (errorMessage.includes('Deployment already in progress')) {
485→        // Extract deployment ID from error message if present
486→        const match = errorMessage.match(/ID:\s*(\d+)/);
487→        const activeDeploymentId = match ? parseInt(match[1], 10) : undefined;
488→
489→        return NextResponse.json(
490→          {
491→            error: 'A deployment is already in progress for this app',
492→            activeDeploymentId,
493→          },
494→          { status: 409 },
495→        );
496→      }
497→
498→      // Validation errors - return 400
499→      if (
500→        errorMessage.includes('required') ||
501→        errorMessage.includes('Invalid') ||
502→        errorMessage.includes('Empty')
503→      ) {
504→        return NextResponse.json({ error: errorMessage }, { status: 400 });
505→      }
506→
507→      return NextResponse.json(
508→        {
509→          error: errorMessage,
510→        },
511→        { status: 500 },
512→      );
513→    }
514→
515→    console.log(
516→      `[api/deployments] Successfully created deployment ${deployment.id} for app ${app.id}`,
517→    );
518→
519→    return NextResponse.json(sanitizeDeployment(deployment), { status: 202 });
520→  },
521→);
522→
523→// eslint-disable-next-line @typescript-eslint/no-explicit-any
524→function sanitizeDeployment(deployment: any) {
525→  return {
526→    id: deployment.id,
527→    status: deployment.status,
528→    created_at: deployment.created_at,
529→    updated_at: deployment.updated_at,
530→    image_tag: deployment.image_tag,
531→    replicas: deployment.replicas,
532→    branch: deployment.branch,
533→    commit_sha: deployment.commit_sha,
534→    commit_message: deployment.commit_message,
535→    error_message: deployment.error_message,
536→    creation_source: deployment.creation_source,
537→    created_by: deployment.created_by,
538→  };
539→}
