import { NextResponse, type NextRequest } from 'next/server';
import { withOAuth, requireScope, type WithOAuthContext } from '@/lib/auth';
import { OAUTH_SCOPES } from '@/lib/oauth';
import { z } from 'zod';
import { getAppById } from '@scp/shared/apps';
import { getOrg } from '@scp/shared/orgs';
import {
  getSpicepodByAppId,
  listDeployments,
  updateSpicepodVersion,
  type DeployableApp,
  type DeployableSpicepod,
} from '@scp/shared/spicepods';
import { SpicepodSchema, type Spicepod } from '@scp/shared/spicepods/schema';
import { getDataPlatform } from '@scp/shared/data-platform';
import { getAppRegion } from '@scp/shared/regions';
import { createSpicepodDeployment } from '@/lib/spicepod/deployments';
import { createVersionUpdateServices } from '@/lib/spicepod/services';

export const dynamic = 'force-dynamic';
export const maxDuration = 300;

type RouteParams = { params: Promise<{ appId: string }> };

/**
 * Deployment schema matching SpicepodSet deployments.
 * The spicepod configuration comes from the app's current config.
 */
const CreateDeploymentSchema = z.object({
  // Optional overrides for this deployment
  image_tag: z.string().optional(),
  replicas: z.number().min(1).max(10).optional(),

  // Git context
  branch: z.string().optional(),
  commit_sha: z.string().optional(),
  commit_message: z.string().optional(),

  // Debug mode
  debug: z.boolean().optional(),
});

/**
 * @swagger
 * /v1/apps/{appId}/deployments:
 *   get:
 *     summary: List deployments
 *     description: Returns a list of deployments for the specified app, similar to SpicepodSet deployments.
 *     security:
 *       - BearerAuth: []
 *     parameters:
 *       - in: path
 *         name: appId
 *         required: true
 *         schema:
 *           type: integer
 *         description: The ID of the app
 *       - in: query
 *         name: limit
 *         schema:
 *           type: integer
 *           default: 20
 *         description: Maximum number of deployments to return
 *       - in: query
 *         name: status
 *         schema:
 *           type: string
 *           enum: [queued, in_progress, succeeded, failed, created]
 *         description: Filter by deployment status
 *     responses:
 *       200:
 *         description: List of deployments
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 deployments:
 *                   type: array
 *                   items:
 *                     $ref: '#/components/schemas/Deployment'
 *       401:
 *         description: Unauthorized
 *       403:
 *         description: Insufficient scope
 *       404:
 *         description: App not found
 *     tags:
 *       - Deployments
 */
export const GET = withOAuth(
  async (
    req: NextRequest,
    { params, oauth, supabase }: WithOAuthContext<RouteParams>,
  ) => {
    const scopeError = requireScope(oauth, OAUTH_SCOPES.DEPLOYMENTS_READ);
    if (scopeError) return scopeError;

    const { appId } = await params.params;
    const appIdNum = parseInt(appId, 10);

    if (isNaN(appIdNum)) {
      return NextResponse.json({ error: 'Invalid app ID' }, { status: 400 });
    }

    const { searchParams } = new URL(req.url);
    const limit = Math.min(
      parseInt(searchParams.get('limit') || '20', 10),
      100,
    );
    const status = searchParams.get('status') as
      | 'queued'
      | 'in_progress'
      | 'succeeded'
      | 'failed'
      | 'created'
      | null;

    // Get the app using shared operation
    const { data: app, error: appError } = await getAppById(
      supabase,
      appIdNum,
      oauth.orgId,
    );

    if (appError) {
      console.error('[api/deployments] Failed to get app:', appError);
      return NextResponse.json({ error: 'Failed to get app' }, { status: 500 });
    }

    if (!app) {
      return NextResponse.json(
        { error: `App with ID ${appId} not found` },
        { status: 404 },
      );
    }

    // Get the spicepod for this app using shared operation
    const { data: spicepod } = await getSpicepodByAppId(supabase, app.id);

    if (!spicepod) {
      return NextResponse.json({ deployments: [] });
    }

    // Get deployments using shared operation
    const options: {
      limit?: number;
      status?: 'queued' | 'in_progress' | 'succeeded' | 'failed' | 'created';
    } = { limit };
    if (status) {
      options.status = status;
    }
    const { data: deployments, error } = await listDeployments(
      supabase,
      spicepod.id,
      options,
    );

    if (error) {
      console.error('[api/deployments] Failed to list deployments:', error);
      return NextResponse.json(
        { error: 'Failed to list deployments' },
        { status: 500 },
      );
    }

    return NextResponse.json({
      deployments: (deployments || []).map(sanitizeDeployment),
    });
  },
);

/**
 * @swagger
 * /v1/apps/{appId}/deployments:
 *   post:
 *     summary: Create deployment
 *     description: |
 *       Creates a new deployment for the specified app using the app's current spicepod configuration.
 *       This is similar to SpicepodSet deployments - the spicepod config is taken from the app,
 *       and you can optionally override image_tag and replicas for this deployment.
 *     security:
 *       - BearerAuth: []
 *     parameters:
 *       - in: path
 *         name: appId
 *         required: true
 *         schema:
 *           type: integer
 *         description: The ID of the app
 *     requestBody:
 *       required: false
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             properties:
 *               image_tag:
 *                 type: string
 *                 description: Override the spice.ai runtime image tag for this deployment
 *               replicas:
 *                 type: integer
 *                 minimum: 1
 *                 maximum: 10
 *                 description: Override the number of replicas for this deployment
 *               branch:
 *                 type: string
 *                 description: Git branch name
 *               commit_sha:
 *                 type: string
 *                 description: Git commit SHA
 *               commit_message:
 *                 type: string
 *                 description: Git commit message
 *               debug:
 *                 type: boolean
 *                 description: Enable debug mode
 *     responses:
 *       202:
 *         description: Deployment created and queued
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Deployment'
 *       400:
 *         description: Invalid request body or app has no spicepod configuration
 *       401:
 *         description: Unauthorized
 *       403:
 *         description: Insufficient scope
 *       404:
 *         description: App not found
 *     tags:
 *       - Deployments
 */
export const POST = withOAuth(
  async (
    req: NextRequest,
    { params, oauth, supabase }: WithOAuthContext<RouteParams>,
  ) => {
    const scopeError = requireScope(oauth, OAUTH_SCOPES.DEPLOYMENTS_WRITE);
    if (scopeError) return scopeError;

    const { appId } = await params.params;
    const appIdNum = parseInt(appId, 10);

    if (isNaN(appIdNum)) {
      return NextResponse.json({ error: 'Invalid app ID' }, { status: 400 });
    }

    let body: unknown = {};
    try {
      const text = await req.text();
      if (text) {
        body = JSON.parse(text);
      }
    } catch {
      return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
    }

    const result = CreateDeploymentSchema.safeParse(body);
    if (!result.success) {
      return NextResponse.json(
        { error: 'Validation error', details: result.error.flatten() },
        { status: 400 },
      );
    }

    // Get the app using shared operation
    const { data: app, error: appError } = await getAppById(
      supabase,
      appIdNum,
      oauth.orgId,
    );

    if (appError) {
      console.error('[api/deployments] Failed to get app:', appError);
      return NextResponse.json({ error: 'Failed to get app' }, { status: 500 });
    }

    if (!app) {
      return NextResponse.json(
        { error: `App with ID ${appId} not found` },
        { status: 404 },
      );
    }

    // Validate required fields
    if (!app.api_key) {
      console.error(`[api/deployments] Missing API key for app ${app.id}`);
      return NextResponse.json(
        { error: 'App API key is required for deployment' },
        { status: 400 },
      );
    }

    if (!app.org_id) {
      console.error(`[api/deployments] Missing org_id for app ${app.id}`);
      return NextResponse.json(
        { error: 'App organization is required for deployment' },
        { status: 400 },
      );
    }

    // Get organization for orgName
    const { data: org, error: orgError } = await getOrg(supabase, {
      id: app.org_id,
    });

    if (orgError || !org) {
      console.error('[api/deployments] Failed to get org:', orgError);
      return NextResponse.json(
        { error: 'Failed to get organization' },
        { status: 500 },
      );
    }

    if (!org.name) {
      console.error(`[api/deployments] Org ${org.id} has no name`);
      return NextResponse.json(
        { error: 'Organization name is required' },
        { status: 500 },
      );
    }

    // Get the spicepod using shared operation - required for deployment
    const { data: spicepodRecord, error: spicepodError } =
      await getSpicepodByAppId(supabase, app.id);

    if (spicepodError) {
      console.error('[api/deployments] Failed to get spicepod:', spicepodError);
      return NextResponse.json(
        { error: 'Failed to get spicepod configuration' },
        { status: 500 },
      );
    }

    if (!spicepodRecord || !spicepodRecord.spicepod) {
      return NextResponse.json(
        {
          error:
            'App has no spicepod configuration. Update the app with a spicepod before deploying.',
        },
        { status: 400 },
      );
    }

    // Check if spicepod is deleted or paused
    if (spicepodRecord.deleted_at) {
      console.error(
        `[api/deployments] Cannot deploy deleted spicepod ${spicepodRecord.id}`,
      );
      return NextResponse.json(
        { error: 'Spicepod has been deleted' },
        { status: 400 },
      );
    }

    if (spicepodRecord.paused_at) {
      console.error(
        `[api/deployments] Cannot deploy paused spicepod ${spicepodRecord.id}`,
      );
      return NextResponse.json(
        { error: 'Spicepod is paused. Please restore it before deploying.' },
        { status: 400 },
      );
    }

    // Update spicepod to latest satisfying version (same as portal flow)
    const region = getAppRegion(app.cname);
    const versionUpdateServices = createVersionUpdateServices();
    try {
      await updateSpicepodVersion(
        supabase,
        app.id,
        region,
        versionUpdateServices,
      );
    } catch (error) {
      console.error(
        `[api/deployments] Failed to update spicepod version for app ${app.id}:`,
        error,
      );
      // Continue with deployment even if version update fails (same as portal behavior)
    }

    // Re-fetch spicepod after potential version update
    const { data: updatedSpicepodRecord, error: refetchError } =
      await getSpicepodByAppId(supabase, app.id);

    if (refetchError || !updatedSpicepodRecord) {
      console.error(
        '[api/deployments] Failed to refetch spicepod after version update:',
        refetchError,
      );
      return NextResponse.json(
        { error: 'Failed to get spicepod configuration after version update' },
        { status: 500 },
      );
    }

    // Parse and validate spicepod configuration (use updated record)
    let parsedSpicepod: Spicepod;
    try {
      parsedSpicepod = SpicepodSchema.parse(updatedSpicepodRecord.spicepod);
    } catch (parseError) {
      console.error(
        '[api/deployments] Invalid spicepod configuration:',
        parseError,
      );
      return NextResponse.json(
        { error: 'Invalid spicepod configuration' },
        { status: 400 },
      );
    }

    // Build deployable app shape
    const deployableApp: DeployableApp = {
      id: app.id,
      org_id: app.org_id,
      api_key: app.api_key,
      name: app.name,
      repo_id: app.repo_id,
      cname: app.cname,
      node_group: app.node_group,
      tags: app.tags,
      nameserver1: app.nameserver1,
      nameserver2: app.nameserver2,
      pvc: app.pvc,
      storage_claim_size_gb: app.storage_claim_size_gb,
    };

    // Build deployable spicepod with parsed configuration (use updated record)
    const deployableSpicepod: DeployableSpicepod = {
      ...updatedSpicepodRecord,
      spicepod: parsedSpicepod,
      // Apply overrides if provided
      image_tag: result.data.image_tag ?? updatedSpicepodRecord.image_tag,
      replicas: result.data.replicas ?? updatedSpicepodRecord.replicas,
      valid: true,
    };

    // Get data platform client
    let dataPlatform;
    try {
      dataPlatform = getDataPlatform(app);
    } catch (error) {
      console.error('[api/deployments] Failed to get data platform:', error);
      return NextResponse.json(
        { error: 'Failed to initialize data platform client' },
        { status: 500 },
      );
    }

    console.log(
      `[api/deployments] Creating deployment for app ${app.id} (${org.name}/${app.name})`,
    );

    // Create deployment using shared helper
    const { data: deployment, error: deploymentError } =
      await createSpicepodDeployment(
        supabase,
        dataPlatform,
        org.name,
        deployableApp,
        deployableSpicepod,
        {
          debug: result.data.debug,
          creationSource: 'api',
        },
      );

    if (deploymentError || !deployment) {
      console.error(
        '[api/deployments] Failed to create deployment:',
        deploymentError,
      );

      // Check for specific error types and return appropriate status codes
      const errorMessage =
        deploymentError?.message || 'Failed to create deployment';

      // Concurrent deployment error - return 409 Conflict
      if (errorMessage.includes('Deployment already in progress')) {
        // Extract deployment ID from error message if present
        const match = errorMessage.match(/ID:\s*(\d+)/);
        const activeDeploymentId = match ? parseInt(match[1], 10) : undefined;

        return NextResponse.json(
          {
            error: 'A deployment is already in progress for this app',
            activeDeploymentId,
          },
          { status: 409 },
        );
      }

      // Validation errors - return 400
      if (
        errorMessage.includes('required') ||
        errorMessage.includes('Invalid') ||
        errorMessage.includes('Empty')
      ) {
        return NextResponse.json({ error: errorMessage }, { status: 400 });
      }

      return NextResponse.json(
        {
          error: errorMessage,
        },
        { status: 500 },
      );
    }

    console.log(
      `[api/deployments] Successfully created deployment ${deployment.id} for app ${app.id}`,
    );

    return NextResponse.json(sanitizeDeployment(deployment), { status: 202 });
  },
);

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function sanitizeDeployment(deployment: any) {
  return {
    id: deployment.id,
    status: deployment.status,
    created_at: deployment.created_at,
    updated_at: deployment.updated_at,
    image_tag: deployment.image_tag,
    replicas: deployment.replicas,
    branch: deployment.branch,
    commit_sha: deployment.commit_sha,
    commit_message: deployment.commit_message,
    error_message: deployment.error_message,
    creation_source: deployment.creation_source,
    created_by: deployment.created_by,
  };
}

