    #[snafu(display(
        "Unable to create data connector: {source} Report a bug to request support: https://github.com/spiceai/spiceai/issues"
    ))]
    UnableToCreateDataConnector {
        source: Box<dyn std::error::Error + Sync + Send>,
    },

    #[snafu(display(
