    }

    /// List available container images.
    pub async fn list_container_images(
        &self,
        channel: Option<&str>,
    ) -> Result<ContainerImagesResponse> {
        use std::fmt::Write;

        let mut url = format!("{}/v1/container-images", self.base_url);
