    // ========================================================================
    // Secrets
    // ========================================================================

    /// List secrets for an app.
    pub async fn list_secrets(&self, app_id: i64) -> Result<Vec<Secret>> {
        let url = format!("{}/v1/apps/{}/secrets", self.base_url, app_id);
