475→fn spiced_starter(mode: SpicedStartMode) -> Box<dyn SpicedStarter + Send + Sync> {
476→    match mode {
477→        SpicedStartMode::Local => Box::new(LocalSpicedStarter),
478→        SpicedStartMode::SpiceCloud => Box::new(SpiceCloudSpicedStarter),
479→    }
