502→/// Create a Flight-based query executor for the given spiced instance.
503→pub(crate) async fn create_query_executor(
504→    spiced_instance: &test_framework::spiced::SpicedInstance,
505→    api_key: Option<String>,
506→) -> anyhow::Result<Box<dyn test_framework::execution::QueryExecutor>> {
507→    let spice_client = spiced_instance.spice_client(api_key, false).await?;
508→    Ok(Box::new(test_framework::execution::FlightExecutor::new(
509→        std::sync::Arc::new(spice_client),
510→    )))
