            anyhow::anyhow!("App API key is required to poll deployment readiness")
        })?;

        // wait_for_deployment_ready uses raw reqwest for the SQL health-check
        let poll_client = Client::builder()
            .timeout(Duration::from_secs(600))
            .build()?;
