    let created = cloud
        .create_deployment(
            app_id,
            &CreateDeploymentRequest {
                image_tag: image_tag.map(String::from),
                replicas: None,
                branch: None,
                commit_sha: None,
                commit_message: None,
                debug: false,
            },
