impl Handler for SpidapterHandler {
    async fn setup(
        &mut self,
        run_id: Uuid,
        datasets: HashMap<String, DatasetConfig>,
    ) -> Result<SetupResponse, String> {
        eprintln!(
            "[stdio] setup: run_id={run_id}, datasets={:?}",
            datasets.keys().collect::<Vec<_>>()
        );

        let state = provision_spice_cloud_app(
            run_id,
            &datasets,
